import { fetchWithFallback } from "./api.js";
import { CONFIG_SERVERS } from "./config.js";
import path from "path"
import { fileURLToPath } from "url";
import { shouldUpdate } from "./versions.js";
import { loadCacheJson, saveCacheJson } from "./cache.js";
import { downloadAssets, pruneAssets, getAssetsDir, getCachedFile } from "./sync.js";
import { PaymentCampaignResponse, PaymentJsonReturnType } from "./types/payment.type.js";

export class PaymentManager {
    __filename : string;
    __dirname : string;


  constructor() {
    this.__filename = fileURLToPath(import.meta.url);
    this.__dirname = path.dirname(this.__filename);
}


async downloadLatestPaymentJson() {
    const url = CONFIG_SERVERS.payment;
    const localPath = path.join(this.__dirname, "../payment/Payment.json");
    return await fetchWithFallback(url, localPath);
} 

 async syncPaymentContent() : Promise<PaymentJsonReturnType | false | null> {
    
    const latestConfig = await this.downloadLatestPaymentJson() as PaymentCampaignResponse;
    
    
    if (!latestConfig) {
        return false;
    }

    if(latestConfig.getPayment == false){
      return null;
    }

    let location = null;
    
    // const latestConfig = filterConfigWithPlatform(config,process.platform);
    
    const cachedConfig = await loadCacheJson("payment.json");

    if (shouldUpdate(latestConfig, cachedConfig, "payment-global-version")) {
        // $$$$$
        // to log payment config update and asset download start
        // console.log("[Targeting] Payment config updated. Downloading new assets...");
        

        await saveCacheJson("payment.json", latestConfig);
        const { ok , campaignDir} = await downloadAssets(latestConfig, "payment", true);
        location = campaignDir;
        if (ok) {
            try {
                await pruneAssets(latestConfig, "payment");
            } catch (pruneErr) {
                // $$$$$
                // to log error pruning payment assets
                // console.error("[Targeting] Failed to prune payment assets:", pruneErr.message);
            }
        }
    } 

    location = getCachedFile("payment");

    return { latestConfig , location};
   }

}
